# region: shape
def shape(raw):
    out = []
    for tok in raw[1:]:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: intake
def intake(xs, offset=4):
    return [v + offset for v in xs]

# region: digest
def digest(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: fold
def fold(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return fold(digest(intake(shape(raw))))

