        self.assertEqual(run(['12', '12', '1']), {'n': 3, 'total': 37, 'flags': ['n', 'total']})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 1, 'total': 4, 'flags': ['n', 'total']})
